before_block:
// Smoothly interpolate camera target & spherical coordinates
camState.target.lerp(camState.desiredTarget, 0.1);
camState.spherical.radius += (camState.desiredSpherical.radius - camState.spherical.radius) * 0.1;
camState.spherical.phi += (camState.desiredSpherical.phi - camState.spherical.phi) * 0.1;
camState.spherical.theta += (camState.desiredSpherical.theta - camState.spherical.theta) * 0.1;

after_block:
// Preserve the 60 Hz camera feel across accepted frame deltas.
const cameraBlend = 1 - Math.pow(0.9, dt * 60);
camState.target.lerp(camState.desiredTarget, cameraBlend);
camState.spherical.radius += (camState.desiredSpherical.radius - camState.spherical.radius) * cameraBlend;
camState.spherical.phi += (camState.desiredSpherical.phi - camState.spherical.phi) * cameraBlend;
camState.spherical.theta += (camState.desiredSpherical.theta - camState.spherical.theta) * cameraBlend;
